export const CHESS_LESSONS = [
  { id:'chess-1', title:'Meet the pieces', subtitle:'Beginner · Lesson 1', stage:'Identifying pieces and their names', step:1, totalSteps:30, tutorInstruction:"Welcome to chess! I am Ms. Momo and I will teach you everything. Today we meet all the chess pieces. Look at my board on the right — I have placed the King on e1. The King is the tall piece with a cross on top. Find e1 on your board — column e, row 1 — and place your King there!", rightPanelNote:"Ms. Momo places the King on e1 — now you try", tip:"The King is the most important piece in chess. If your King is captured, the game is over. Always protect your King!", targetPiece:'K', targetSquare:[7,4] },
  { id:'chess-2', title:'The Queen', subtitle:'Beginner · Lesson 2', stage:'The most powerful piece', step:2, totalSteps:30, tutorInstruction:"Now meet the Queen — the most powerful piece on the board! She can move in any direction: forward, backward, sideways, or diagonally — as many squares as she likes. Place the White Queen on d1. Remember: the Queen always starts on her own colour. White Queen on a light square!", rightPanelNote:"Ms. Momo places the Queen on d1 — now you try", tip:"The Queen starts on d1. White Queen on light, Black Queen on dark. An easy way to remember: the Queen is proud and always stands on her own colour!", targetPiece:'Q', targetSquare:[7,3] },
  { id:'chess-3', title:'Rooks, Bishops and Knights', subtitle:'Beginner · Lesson 3', stage:'The remaining pieces', step:3, totalSteps:30, tutorInstruction:"Three more pieces to meet! The Rook looks like a castle tower and moves in straight lines. The Bishop moves diagonally and always stays on the same colour. The Knight looks like a horse and moves in an L-shape — it can even jump over other pieces! Set up your full back row.", rightPanelNote:"Ms. Momo shows the complete back row", tip:"Back row from left to right: Rook, Knight, Bishop, Queen, King, Bishop, Knight, Rook. An easy way to remember: Rooks go in the corners and Knights ride next to them!", targetPiece:null, targetSquare:null },
  { id:'chess-4', title:'The Pawns', subtitle:'Beginner · Lesson 4', stage:'Your army of eight', step:4, totalSteps:30, tutorInstruction:"Now we place the pawns — your army of eight soldiers! Pawns go on row 2 for White, one on every square from a2 to h2. Pawns move forward one square at a time, but on their very first move they can choose to move two squares. They capture diagonally. Place all 8 pawns!", rightPanelNote:"Ms. Momo fills row 2 with pawns", tip:"Pawns can only move forward, never backward. They capture diagonally. A pawn that reaches the other end of the board can become a Queen — that is called promotion!", targetPiece:'P', targetSquare:null },
  { id:'chess-5', title:'How the King moves', subtitle:'Beginner · Lesson 5', stage:'One square in any direction', step:5, totalSteps:30, tutorInstruction:"Every piece has its own way of moving. The King can move exactly one square in any direction — forward, backward, sideways, or diagonally. He is not very fast but he is very important. Click on the King on your board and I will show you all the squares he can reach.", rightPanelNote:"The highlighted squares show where the King can move", tip:"The King can move one square in any of the 8 directions around him. He cannot move to a square where he would be in danger — that is called moving into check!", targetPiece:null, targetSquare:null },
  { id:'chess-6', title:'How the Rook moves', subtitle:'Beginner · Lesson 6', stage:'Straight lines in all four directions', step:6, totalSteps:30, tutorInstruction:"The Rook is a powerful piece. It moves in straight lines — forward, backward, left, or right — as many squares as it likes. It cannot jump over other pieces. Two Rooks working together are very powerful. Click on a Rook to see its moves!", rightPanelNote:"Ms. Momo shows the Rook moving along files and ranks", tip:"The Rook moves along ranks (rows) and files (columns). It is most powerful on open files — columns with no pawns blocking the way. Rooks love open space!", targetPiece:null, targetSquare:null },
  { id:'chess-7', title:'How the Bishop moves', subtitle:'Beginner · Lesson 7', stage:'Diagonals only', step:7, totalSteps:30, tutorInstruction:"The Bishop moves diagonally — always staying on the same colour. Each player starts with two Bishops: one on light squares and one on dark squares. A Bishop can move as many squares as it likes diagonally but it can never change colour. Click on a Bishop to see its moves!", rightPanelNote:"Ms. Momo shows the Bishop moving diagonally", tip:"Each Bishop stays on its own colour forever. A Bishop on light squares will never reach a dark square. This is why having both Bishops is so valuable — together they cover all squares!", targetPiece:null, targetSquare:null },
  { id:'chess-8', title:'How the Knight moves', subtitle:'Beginner · Lesson 8', stage:'The L-shaped jump', step:8, totalSteps:30, tutorInstruction:"The Knight is the trickiest piece to learn — but also the most exciting! It moves in an L-shape: two squares in one direction and then one square sideways. The Knight is the ONLY piece that can jump over other pieces. Click on a Knight and try to find all eight squares it can reach!", rightPanelNote:"Ms. Momo demonstrates the Knight's eight possible moves", tip:"Remember the Knight's move like this: two and then one, then turn. From the centre of the board a Knight can reach eight different squares. Knights are most powerful near the centre!", targetPiece:null, targetSquare:null },
  { id:'chess-9', title:'How the Queen moves', subtitle:'Beginner · Lesson 9', stage:'The powerhouse', step:9, totalSteps:30, tutorInstruction:"The Queen combines the power of the Rook and the Bishop! She can move in any direction — forward, backward, sideways, and diagonally — as many squares as she likes. From the centre of the board the Queen can reach 27 different squares. She is the most powerful piece!", rightPanelNote:"Ms. Momo shows the Queen's extraordinary range", tip:"The Queen is so powerful that losing her is almost always a disaster. Protect your Queen carefully and look for opportunities to bring her into the game at the right moment!", targetPiece:null, targetSquare:null },
  { id:'chess-10', title:'How Pawns move and capture', subtitle:'Beginner · Lesson 10', stage:'Forward march', step:10, totalSteps:30, tutorInstruction:"Pawns are special! They move forward but capture diagonally. On their very first move each pawn can choose to move one or two squares forward. After that, only one square at a time. If a pawn reaches the other end of the board it becomes a Queen — the most exciting moment in chess!", rightPanelNote:"Ms. Momo shows pawn movement and capture", tip:"Pawns can only move forward and capture forward-diagonally. They can never move backward. A promoted pawn becomes a Queen in most cases — that is called queening a pawn!", targetPiece:null, targetSquare:null },
  { id:'chess-11', title:'Check — attacking the King', subtitle:'Tactics · Lesson 11', stage:'Threatening the King', step:11, totalSteps:30, tutorInstruction:"When you attack the opponent's King directly, that is called CHECK. The opponent must immediately deal with the check — they cannot ignore it. They can block the check, move the King to safety, or capture the attacking piece. Watch how I put the King in check!", rightPanelNote:"Ms. Momo demonstrates a check position", tip:"When you are in check you MUST respond. You cannot make any other move. There are only three ways to escape check: move the King, block the check, or capture the checking piece.", targetPiece:null, targetSquare:null },
  { id:'chess-12', title:'Checkmate — winning the game', subtitle:'Tactics · Lesson 12', stage:'The winning move', step:12, totalSteps:30, tutorInstruction:"CHECKMATE is when the King is in check and there is no way to escape. The game is over and the player who delivers checkmate wins! Watch this famous checkmate pattern — the Scholar's Mate — and learn to both use it and defend against it.", rightPanelNote:"Ms. Momo shows the Scholar's Mate in four moves", tip:"Checkmate ends the game immediately. The King does not need to be actually captured — just trapped with no escape. Always look for checkmate threats in every game!", targetPiece:null, targetSquare:null },
  { id:'chess-13', title:'The Fork — attacking two pieces', subtitle:'Tactics · Lesson 13', stage:'Double attack', step:13, totalSteps:30, tutorInstruction:"A FORK is when one piece attacks two of the opponent's pieces at the same time. The opponent can only save one — so you capture the other for free! Knights are especially good at forking because of their unusual L-shaped move. Look for the fork in this position!", rightPanelNote:"Ms. Momo shows a Knight fork attacking Queen and Rook", tip:"The best forks attack the King plus another piece — then the opponent MUST move the King and you capture the other piece for free. Always look for fork opportunities!", targetPiece:null, targetSquare:null },
  { id:'chess-14', title:'The Pin — holding pieces in place', subtitle:'Tactics · Lesson 14', stage:'Immobilising the enemy', step:14, totalSteps:30, tutorInstruction:"A PIN is when you attack a piece that cannot move because it would expose a more valuable piece behind it. If a Bishop is pinned against a King it cannot move because moving it would put the King in check! Find the pinned piece in this position.", rightPanelNote:"Ms. Momo demonstrates an absolute pin against the King", tip:"A piece that is absolutely pinned against the King cannot move at all — it would be illegal! A relative pin is against a Queen or Rook — the piece CAN move but it would be a bad trade.", targetPiece:null, targetSquare:null },
  { id:'chess-15', title:'The Skewer — forcing a move', subtitle:'Tactics · Lesson 15', stage:'Attack the bigger piece', step:15, totalSteps:30, tutorInstruction:"A SKEWER is like a reversed pin. You attack a valuable piece — usually the King or Queen — and when it moves away, you capture the less valuable piece hiding behind it. It is the opposite of a pin! Find the skewer move in this position.", rightPanelNote:"Ms. Momo shows a Bishop skewering King and Rook", tip:"Pins and skewers both use the idea of pieces on a line. In a pin the less valuable piece is in front. In a skewer the more valuable piece is in front and must move.", targetPiece:null, targetSquare:null },
  { id:'chess-16', title:'Discovered attack', subtitle:'Tactics · Lesson 16', stage:'Hiding your weapon', step:16, totalSteps:30, tutorInstruction:"A DISCOVERED ATTACK happens when you move one piece out of the way and it reveals an attack by the piece behind it. The moved piece can also make a threat at the same time — creating two attacks at once! This is one of the most powerful tactics in chess.", rightPanelNote:"Ms. Momo shows a discovered attack creating double threats", tip:"Discovered attacks are powerful because the opponent must deal with two threats. Usually they can only deal with one, so you win material from the other!", targetPiece:null, targetSquare:null },
  { id:'chess-17', title:'Opening principles', subtitle:'Strategy · Lesson 17', stage:'The first moves', step:17, totalSteps:30, tutorInstruction:"Good chess starts with good opening principles! There are three golden rules: control the centre, develop your pieces, and keep your King safe. Let me show you why these matter and how to apply them in your first moves.", rightPanelNote:"Ms. Momo demonstrates the Italian Opening", tip:"The four central squares — d4, d5, e4, e5 — are the most important squares on the board. Control them with your pieces and pawns in the opening and you will always have a strong position!", targetPiece:null, targetSquare:null },
  { id:'chess-18', title:'Castling — King safety', subtitle:'Strategy · Lesson 18', stage:'The special King move', step:18, totalSteps:30, tutorInstruction:"CASTLING is the only move where two pieces move at the same time. The King moves two squares towards a Rook and the Rook jumps to the other side of the King. Castling puts the King in safety behind a wall of pawns. Learn when and how to castle!", rightPanelNote:"Ms. Momo demonstrates both kingside and queenside castling", tip:"You can only castle if neither the King nor the Rook has moved before, there are no pieces between them, the King is not in check, and the King does not pass through check.", targetPiece:null, targetSquare:null },
  { id:'chess-19', title:'Pawn structure', subtitle:'Strategy · Lesson 19', stage:'The skeleton of your position', step:19, totalSteps:30, tutorInstruction:"Pawns cannot move backward so pawn decisions are permanent. Doubled pawns are weak. Isolated pawns are hard to defend. Passed pawns — pawns that cannot be blocked or captured by enemy pawns — are very powerful. Learn to think about pawn structure!", rightPanelNote:"Ms. Momo shows examples of strong and weak pawn structures", tip:"Think of pawns as the backbone of your position. A strong pawn structure gives your pieces good squares to work from. Weak pawns give the opponent targets to attack!", targetPiece:null, targetSquare:null },
  { id:'chess-20', title:'Piece coordination', subtitle:'Strategy · Lesson 20', stage:'Working as a team', step:20, totalSteps:30, tutorInstruction:"Chess pieces are most powerful when they work together. A Bishop and Knight can cover squares the other cannot reach. Two Rooks on open files are twice as powerful as one. Today we learn how to coordinate pieces and create attacking threats together.", rightPanelNote:"Ms. Momo demonstrates a Rook and Bishop battery", tip:"Ask yourself: are my pieces working together or independently? Pieces that coordinate and support each other are far more powerful than the same pieces acting alone!", targetPiece:null, targetSquare:null },
  { id:'chess-21', title:'The back rank mate', subtitle:'Tactics · Lesson 21', stage:'The classic mating pattern', step:21, totalSteps:30, tutorInstruction:"The BACK RANK MATE is one of the most common checkmates in chess. It happens when the King is trapped on the back rank by its own pawns and a Rook or Queen delivers checkmate. Look for back rank threats in every game — and protect against them!", rightPanelNote:"Ms. Momo shows a back rank mate and how to prevent it", tip:"To prevent back rank mate give your King an escape square by moving a pawn one step forward. This is called giving the King air. Always check if you have back rank weakness!", targetPiece:null, targetSquare:null },
  { id:'chess-22', title:'The Sicilian Defence', subtitle:'Openings · Lesson 22', stage:'Fighting for the centre', step:22, totalSteps:30, tutorInstruction:"The Sicilian Defence is the most popular chess opening in the world. Black plays c5 in response to White's e4, immediately fighting for central control in an asymmetric way. Many world champions have used the Sicilian. Today we learn its basic ideas.", rightPanelNote:"Ms. Momo plays through the main Sicilian lines", tip:"The Sicilian creates unbalanced positions where both sides have chances. Black gives up the centre immediately but fights to take it back. It leads to exciting, sharp games!", targetPiece:null, targetSquare:null },
  { id:'chess-23', title:'King and Pawn endgame', subtitle:'Endgames · Lesson 23', stage:'Winning the endgame', step:23, totalSteps:30, tutorInstruction:"Endgames are the final phase of a chess game when most pieces have been traded. In a King and Pawn endgame the King becomes an active fighter. The key rule is: use your King! An active King in the endgame is worth more than a timid one.", rightPanelNote:"Ms. Momo demonstrates the key of the position concept", tip:"In King and Pawn endgames the concept of opposition is crucial. When Kings face each other with one square between them, the player whose turn it is NOT to move has the opposition — an advantage.", targetPiece:null, targetSquare:null },
  { id:'chess-24', title:'Rook endgames', subtitle:'Endgames · Lesson 24', stage:'The most common endgame', step:24, totalSteps:30, tutorInstruction:"Rook endgames are the most common type of endgame in chess. The basic principle is: activate your Rook! Rooks belong behind passed pawns, on open files, and on the seventh rank. Learn the Lucena and Philidor positions — the two most important rook endgames.", rightPanelNote:"Ms. Momo teaches the Lucena position — winning with Rook and Pawn", tip:"A Rook on the seventh rank is extremely powerful because it attacks all the opponent's pawns from behind and cuts off the King. Always try to place your Rook on the seventh!", targetPiece:null, targetSquare:null },
  { id:'chess-25', title:'Calculation and planning', subtitle:'Mastery · Lesson 25', stage:'Thinking ahead', step:25, totalSteps:30, tutorInstruction:"Strong chess players calculate — they see moves ahead in their minds before playing them. Today we practise calculation with progressively deeper puzzles. For each position find the best move and explain why it works. Think before you move!", rightPanelNote:"Ms. Momo presents calculation puzzles of increasing depth", tip:"When calculating always ask: what does my opponent want to do? What is the best square for each of my pieces? Can I create a threat that my opponent cannot deal with?", targetPiece:null, targetSquare:null },
  { id:'chess-26', title:'Defensive techniques', subtitle:'Mastery · Lesson 26', stage:'Saving difficult positions', step:26, totalSteps:30, tutorInstruction:"Every player gets into trouble sometimes. Great players know how to defend and escape bad positions. Today we learn defensive techniques: trading attacking pieces, creating counterplay, building a fortress, and finding perpetual check.", rightPanelNote:"Ms. Momo demonstrates key defensive resources", tip:"Defence requires the same creative thinking as attack. Look for ways to trade off the opponent's most dangerous pieces and create counter-threats. A good defender never gives up!", targetPiece:null, targetSquare:null },
  { id:'chess-27', title:'Nigerian chess champions', subtitle:'Mastery · Lesson 27', stage:'Our champions', step:27, totalSteps:30, tutorInstruction:"Nigeria has produced some remarkable chess players who have competed at the highest levels. Today we study their games and learn from their techniques. Chess is growing fast in Nigeria and the next great champion might be you!", rightPanelNote:"Ms. Momo presents a game by a Nigerian champion", tip:"Every great chess player learned by studying the games of masters who came before them. When you study master games you absorb patterns and ideas that improve your play automatically.", targetPiece:null, targetSquare:null },
  { id:'chess-28', title:'Building an attack', subtitle:'Mastery · Lesson 28', stage:'Creating threats', step:28, totalSteps:30, tutorInstruction:"A chess attack is not just random aggression — it is a systematic build-up of pressure. Today we learn how to identify attacking targets, bring all your pieces to the right squares, create multiple threats, and deliver the decisive blow.", rightPanelNote:"Ms. Momo demonstrates a systematic kingside attack", tip:"Before attacking make sure your own King is safe and all your pieces are actively placed. An attack that fails because you had weak pieces elsewhere is called overextending.", targetPiece:null, targetSquare:null },
  { id:'chess-29', title:'Tournament preparation', subtitle:'Mastery · Lesson 29', stage:'Playing your best', step:29, totalSteps:30, tutorInstruction:"Today we prepare for tournament play. Managing your time, avoiding blunders, staying calm under pressure, and playing your best chess when it matters most. These mental skills are just as important as technical knowledge.", rightPanelNote:"Ms. Momo shares tournament preparation strategies", tip:"In a tournament never play quickly just because your opponent is playing quickly. Use your time wisely, especially in complicated positions. One bad move can undo a whole game of good play.", targetPiece:null, targetSquare:null },
  { id:'chess-30', title:'Your best game', subtitle:'Mastery · Lesson 30', stage:'Play your finest chess', step:30, totalSteps:30, tutorInstruction:"This is the final lesson of the chess curriculum. You have come from knowing nothing about the pieces to understanding tactics, strategy, openings and endgames. Today you play your best game against me with everything you have learned. Show me what you know!", rightPanelNote:"Ms. Momo plays at medium strength — your strongest opponent yet", tip:"Apply everything you have learned: control the centre, develop pieces, castle early, look for tactics, build a plan, and stay alert to your opponent's threats. Play your finest chess!", targetPiece:null, targetSquare:null },
];

